        # cold launch, or the emulator restarted.
        if WS_CACHE.exists():
            WS_CACHE.unlink(missing_ok=True)
        _resolve_ws(serial=serial, force=True)
        return _ext_resilient(ext_method, params, serial=serial, _retried=True)


